css:
.cold-sim-container {
    padding: 28px;
    background: #f4f6f9;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1d2939;
}
.cold-sim-header {
    background: #ffffff;
    border-left: 5px solid #0a66c2;
    padding: 22px 28px;
    border-radius: 6px;
    margin-bottom: 20px;
    box-shadow: 0 1px 3px rgba(16,24,40,0.06);
}
.cold-sim-header h1 {
    font-size: 1.7rem;
    font-weight: 700;
    margin: 0 0 4px 0;
    color: #0a66c2;
    letter-spacing: -0.01em;
}
.cold-sim-subtitle {
    color: #475467;
    font-size: 0.95rem;
}
.cold-sim-period-counter {
    background: #ffffff;
    padding: 10px 18px;
    border-radius: 24px;
    margin-bottom: 22px;
    font-size: 0.9rem;
    color: #475467;
    border: 1px solid #e4e7ec;
    display: inline-block;
    font-weight: 500;
}
.cold-sim-period-counter span#currentDay,
.cold-sim-period-counter span#maxPeriods {
    color: #0a66c2;
    font-weight: 700;
}
.cold-sim-kpis {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 14px;
    margin-bottom: 22px;
}
.cold-sim-kpi {
    background: #ffffff;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    padding: 20px 22px;
    position: relative;
    overflow: hidden;
}
.cold-sim-kpi::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #0a66c2, #2e90fa);
}
.cold-sim-kpi-label {
    color: #667085;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
    font-weight: 600;
}
.cold-sim-kpi-value {
    font-size: 2.1rem;
    font-weight: 700;
    color: #0a66c2;
    line-height: 1.1;
}
.cold-sim-briefing {
    background: #fff7ed;
    border-left: 4px solid #f59e0b;
    padding: 16px 22px;
    border-radius: 4px;
    margin-bottom: 22px;
}
.cold-sim-briefing-title {
    font-weight: 700;
    color: #92400e;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 6px;
}
.cold-sim-briefing-text {
    color: #78350f;
    font-size: 0.95rem;
    line-height: 1.55;
}
.cold-sim-workspace {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 22px;
}
.cold-sim-controls {
    background: #ffffff;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    padding: 22px;
}
.cold-sim-controls h3 {
    margin: 0 0 16px 0;
    font-size: 1.05rem;
    color: #1d2939;
    font-weight: 700;
}
.cold-sim-round-block label {
    display: block;
    margin-top: 12px;
    margin-bottom: 6px;
    font-size: 0.82rem;
    font-weight: 600;
    color: #344054;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}
.cold-sim-select,
.cold-sim-controls input[type="text"],
.cold-sim-controls input[type="number"] {
    width: 100%;
    background: #ffffff;
    border: 1px solid #d0d5dd;
    color: #1d2939;
    border-radius: 6px;
    padding: 9px 12px;
    font-size: 0.92rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.cold-sim-select:focus,
.cold-sim-controls input:focus {
    outline: none;
    border-color: #0a66c2;
    box-shadow: 0 0 0 3px rgba(10,102,194,0.15);
}
.cold-sim-select option {
    background: #ffffff;
    color: #1d2939;
}
.cold-sim-hint {
    font-size: 0.8rem;
    color: #667085;
    margin-top: 8px;
    font-style: italic;
}
.cold-sim-submit {
    margin-top: 20px;
    background: #0a66c2;
    border-color: #0a66c2;
    padding: 10px 22px;
    font-weight: 600;
    border-radius: 6px;
    transition: background 0.2s ease, border-color 0.2s ease;
}
.cold-sim-submit:hover {
    background: #084e94;
    border-color: #084e94;
}
.cold-sim-undo {
    margin-top: 20px;
    margin-left: 8px;
}
.cold-sim-preview {
    background: #ffffff;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    padding: 24px;
    box-shadow: 0 1px 2px rgba(16,24,40,0.04);
}
.cold-sim-preview-title {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #667085;
    font-weight: 700;
    margin-bottom: 14px;
}
.cold-sim-preview-subject {
    font-weight: 600;
    color: #1d2939;
    padding-bottom: 12px;
    border-bottom: 1px solid #e4e7ec;
    margin-bottom: 14px;
    font-size: 1rem;
}
.cold-sim-preview-subject span[data-i18n="subject_prefix"] {
    color: #667085;
    font-weight: 500;
}
.cold-sim-preview-body {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #344054;
    white-space: pre-line;
    min-height: 100px;
}
.cold-sim-preview-signoff {
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px solid #e4e7ec;
    color: #475467;
    font-size: 0.9rem;
    line-height: 1.5;
}
.cold-sim-coach {
    background: #ecfdf5;
    border-left: 4px solid #10b981;
    padding: 16px 22px;
    border-radius: 4px;
    margin-bottom: 22px;
}
.cold-sim-coach-title {
    font-weight: 700;
    color: #065f46;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 6px;
}
.cold-sim-coach-text {
    color: #065f46;
    font-size: 0.95rem;
    line-height: 1.55;
}
.cold-sim-history {
    background: #ffffff;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    padding: 22px;
    margin-bottom: 22px;
}
.cold-sim-history h3 {
    margin: 0 0 14px 0;
    font-size: 1rem;
    color: #1d2939;
    font-weight: 700;
}
.cold-sim-history table {
    margin: 0;
    font-size: 0.9rem;
}
.cold-sim-history th {
    background: #f4f6f9;
    color: #475467;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-color: #e4e7ec;
    font-weight: 700;
}
.cold-sim-history td {
    color: #1d2939;
    border-color: #e4e7ec;
}
.cold-sim-chart-wrap {
    background: #ffffff;
    border: 1px solid #e4e7ec;
    border-radius: 8px;
    padding: 22px;
    height: 340px;
}
@media (max-width: 768px) {
    .cold-sim-container { padding: 16px; }
    .cold-sim-workspace { grid-template-columns: 1fr; }
    .cold-sim-kpi-value { font-size: 1.6rem; }
    .cold-sim-header h1 { font-size: 1.3rem; }
}

