(function() {
    'use strict';

    class ColdOutreachAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'ColdOutreach';
            this.version = '1.1.0';

            this.SUBJECT_OPTIONS = {
                A: { text: 'Quick question', specificity: 1, baseRate: 7, words: 2 },
                B: { text: 'Connecting', specificity: 1, baseRate: 5, words: 1 },
                C: { text: 'Re: your recent post', specificity: 2, baseRate: 10, words: 4 },
                D: { text: 'Maria Chen suggested I write — 25 min on B2B pricing', specificity: 5, baseRate: 35, words: 11 },
                E: { text: 'Question on your 2024 article on B2B churn', specificity: 4, baseRate: 25, words: 9 }
            };

            this.OPENER_OPTIONS = {
                A: { text: 'I hope this email finds you well.', specificity: 1, words: 7, lift: -3 },
                B: { text: 'Hi — I am head of ops at Acme. Writing because I read your churn piece carefully.', specificity: 4, words: 16, lift: 4 },
                C: { text: 'Full LinkedIn bio: 12 years at Stripe, then VP at Acme since 2019, MBA from INSEAD, formerly at McKinsey...', specificity: 1, words: 19, lift: -5 }
            };

            this.REASON_OPTIONS = {
                A: { text: 'You have had an inspiring career.', specificity: 1, words: 6, lift: -2 },
                B: { text: 'Your point in the May 2024 article — that retention is a pricing problem, not a CS problem — changed how we run our QBR.', specificity: 5, words: 26, lift: 6 },
                C: { text: '', specificity: 0, words: 0, lift: -3 }
            };

            this.ASK_OPTIONS = {
                A: { text: 'Could I pick your brain sometime soon?', specificity: 1, words: 7, lift: -4 },
                B: { text: 'Would love to connect.', specificity: 1, words: 4, lift: -3 },
                C: { text: 'Could I have 25 minutes in the next 3 weeks?', specificity: 5, words: 10, lift: 6 }
            };

            this.EASYOUT_OPTIONS = {
                A: { text: 'If timing is bad, no worries — I would value being able to reach out again.', specificity: 4, words: 16, lift: 3 },
                B: { text: '', specificity: 0, words: 0, lift: -1 }
            };

            this.SIGNOFF_OPTIONS = {
                A: { text: 'Joaquim — Head of Ops, Acme · acme.com/cases/2024', specificity: 4, words: 9, lift: 2 },
                B: { text: 'Joaquim Virgili (linkedin.com/in/jvirgili) — 12 years at Stripe, INSEAD MBA, formerly at McKinsey', specificity: 1, words: 14, lift: -2 },
                C: { text: 'J.', specificity: 1, words: 1, lift: -1 }
            };

            this.FOLLOWUP_OPTIONS = {
                A: { specificity: 0, lift: -2, label: 'Zero follow-ups' },
                B: { specificity: 4, lift: 4, label: 'One follow-up at day 7' },
                C: { specificity: 1, lift: -3, label: 'Three follow-ups (day 3, 7, 14)' }
            };

            this.ROUNDS = [
                {
                    id: 1,
                    block: 'round1Block',
                    descKey: 'briefing_r1'
                },
                {
                    id: 2,
                    block: 'round2Block',
                    descKey: 'briefing_r2'
                },
                {
                    id: 3,
                    block: 'round3Block',
                    descKey: 'briefing_r3'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    replyRate: 0,
                    specificityScore: 0,
                    wordCount: 0,
                    subjectChoice: null,
                    openerChoice: null,
                    reasonChoice: null,
                    askChoice: null,
                    easyOutChoice: null,
                    signoffChoice: null,
                    followupChoice: null,
                    replyRateHistory: [],
                    specificityHistory: [],
                    coachMessage: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    subjectChoice: 'D',
                    openerChoice: 'B',
                    reasonChoice: 'B',
                    askChoice: 'C',
                    easyOutChoice: 'A',
                    signoffChoice: 'A',
                    followupChoice: 'B'
                };
            }
            var self = this;
            setTimeout(function() {
                self._updateBriefing(state);
                self._livePreview();
                if (state.domainState.coachMessage) {
                    self._updateCoach(state.domainState.coachMessage);
                }
            }, 50);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            this._updateBriefing(state);
            var period = state.currentPeriod;

            if (period === 1) {
                var s = document.getElementById('subjectInput');
                if (s) decisions.subjectChoice = s.value;
                if (!decisions.subjectChoice) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('subject_required'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var o = document.getElementById('openerInput');
                var r = document.getElementById('reasonInput');
                var a = document.getElementById('askInput');
                var e = document.getElementById('easyOutInput');
                if (o) decisions.openerChoice = o.value;
                if (r) decisions.reasonChoice = r.value;
                if (a) decisions.askChoice = a.value;
                if (e) decisions.easyOutChoice = e.value;
                if (!decisions.openerChoice || !decisions.reasonChoice || !decisions.askChoice || !decisions.easyOutChoice) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('body_required'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var sg = document.getElementById('signoffInput');
                var fu = document.getElementById('followupInput');
                if (sg) decisions.signoffChoice = sg.value;
                if (fu) decisions.followupChoice = fu.value;
                if (!decisions.signoffChoice || !decisions.followupChoice) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('close_required'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var period = state.currentPeriod;
            var replyRate = state.domainState.replyRate || 0;
            var specificity = state.domainState.specificityScore || 0;
            var words = state.domainState.wordCount || 0;
            var coachMessage = '';

            if (period === 1) {
                var opt = this.SUBJECT_OPTIONS[d.subjectChoice];
                state.domainState.subjectChoice = d.subjectChoice;
                replyRate = opt.baseRate;
                specificity = opt.specificity;
                words = opt.words;
                if (opt.specificity <= 2) {
                    coachMessage = window.mySimulation.t('coach_subj_generic');
                } else if (opt.specificity === 5) {
                    coachMessage = window.mySimulation.t('coach_subj_strong');
                } else {
                    coachMessage = window.mySimulation.t('coach_subj_decent');
                }
            } else if (period === 2) {
                var op = this.OPENER_OPTIONS[d.openerChoice];
                var re = this.REASON_OPTIONS[d.reasonChoice];
                var as = this.ASK_OPTIONS[d.askChoice];
                var eo = this.EASYOUT_OPTIONS[d.easyOutChoice];
                state.domainState.openerChoice = d.openerChoice;
                state.domainState.reasonChoice = d.reasonChoice;
                state.domainState.askChoice = d.askChoice;
                state.domainState.easyOutChoice = d.easyOutChoice;
                var lift = op.lift + re.lift + as.lift + eo.lift;
                replyRate = Math.max(2, replyRate + lift);
                specificity += op.specificity + re.specificity + as.specificity + eo.specificity;
                words += op.words + re.words + as.words + eo.words;

                var issues = [];
                if (op.specificity <= 1) issues.push(window.mySimulation.t('coach_body_throat'));
                if (re.specificity <= 1) issues.push(window.mySimulation.t('coach_body_substance'));
                if (as.specificity <= 1) issues.push(window.mySimulation.t('coach_body_ask'));
                if (eo.specificity === 0) issues.push(window.mySimulation.t('coach_body_easyout'));
                coachMessage = issues.length === 0
                    ? window.mySimulation.t('coach_body_tight')
                    : issues.join(' ');
            } else if (period === 3) {
                var sgo = this.SIGNOFF_OPTIONS[d.signoffChoice];
                var fup = this.FOLLOWUP_OPTIONS[d.followupChoice];
                state.domainState.signoffChoice = d.signoffChoice;
                state.domainState.followupChoice = d.followupChoice;
                replyRate = Math.max(2, replyRate + sgo.lift + fup.lift);
                specificity += sgo.specificity + fup.specificity;
                words += sgo.words || 0;

                var parts = [];
                if (sgo.specificity <= 1) parts.push(window.mySimulation.t('coach_close_signoff'));
                if (d.followupChoice === 'C') parts.push(window.mySimulation.t('coach_close_too_many'));
                if (d.followupChoice === 'A') parts.push(window.mySimulation.t('coach_close_no_followup'));
                coachMessage = parts.length === 0
                    ? window.mySimulation.t('coach_close_clean')
                    : parts.join(' ');
            }

            replyRate = Math.min(60, Math.max(2, replyRate));
            state.domainState.replyRate = replyRate;
            state.domainState.specificityScore = Math.min(20, specificity);
            state.domainState.wordCount = words;
            state.domainState.coachMessage = coachMessage;
            // Rebuild the series from committed history (state.history holds prior committed rounds),
            // then append the current result. This makes the arrays idempotent under undo — including
            // undo back to the start — so they can never double-count a resubmitted round.
            state.domainState.replyRateHistory = (state.history || []).map(function(h) { return (h.results && typeof h.results.replyRate === 'number') ? h.results.replyRate : 0; });
            state.domainState.specificityHistory = (state.history || []).map(function(h) { return (h.results && typeof h.results.specificity === 'number') ? h.results.specificity : 0; });
            state.domainState.replyRateHistory.push(replyRate);
            state.domainState.specificityHistory.push(state.domainState.specificityScore);

            var self = this;
            // The framework advances currentPeriod synchronously once calculateResults returns (and
            // holds it on the final round). Reading the LIVE state on the next tick keeps the briefing,
            // the visible round block, and the preview in sync with the round actually being composed.
            // The previous code added +1 to an already-incremented value, so it skipped the body round.
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
                self._livePreview();
            }, 0);
            setTimeout(function() {
                self._updateCoach(coachMessage);
            }, 400);

            return {
                period: state.currentPeriod,
                replyRate: replyRate,
                specificity: state.domainState.specificityScore,
                wordCount: words,
                coachMessage: coachMessage
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('replyRateDisplay', 'domainState.replyRate', (v) => Math.round(v) + '%');
            uiManager.bind('specificityDisplay', 'domainState.specificityScore', (v) => v + '/20');
            uiManager.bind('lengthDisplay', 'domainState.wordCount', (v) => v + ' words');

            // Live message preview: re-render the email as the player changes any option,
            // instead of only after the round is submitted.
            var self = this;
            ['subjectInput', 'openerInput', 'reasonInput', 'askInput', 'easyOutInput', 'signoffInput', 'followupInput'].forEach(function(id) {
                var el = document.getElementById(id);
                if (!el) return;
                var handler = function() { try { self._livePreview(); } catch (e) {} };
                el.addEventListener('change', handler);
                el.addEventListener('input', handler);
            });
        }

        getChartConfig() {
            return {
                replyRateChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Predicted Reply Rate (%)',
                            data: [],
                            borderColor: '#0a66c2',
                            backgroundColor: 'rgba(10,102,194,0.12)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.25,
                            pointRadius: 6,
                            pointBackgroundColor: '#0a66c2',
                            pointBorderColor: '#ffffff',
                            pointBorderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Reply Rate Across Rounds', color: '#1d2939' },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, suggestedMax: 60, title: { display: true, text: '% reply' } },
                            x: { title: { display: true, text: 'Round' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            // Derive the plotted series from committed history so the chart stays correct through undo.
            var series = (state.history || []).map(function(h) { return (h.results && typeof h.results.replyRate === 'number') ? h.results.replyRate : 0; });
            var labels = series.map(function(_, i) { return 'R' + (i + 1); });
            return {
                replyRateChart: {
                    labels: labels,
                    datasets: [{ data: series }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var finalRate = (last.results && last.results.replyRate) || 0;
            var finalSpec = (last.results && last.results.specificity) || 0;
            var finalWords = (last.results && last.results.wordCount) || 0;
            var performance, tier;
            var insights = [];
            if (finalRate >= 35) {
                tier = 'excellent';
                performance = window.mySimulation.t('perf_excellent');
                insights.push(window.mySimulation.t('insight_excellent_1'));
                insights.push(window.mySimulation.t('insight_excellent_2'));
            } else if (finalRate >= 20) {
                tier = 'good';
                performance = window.mySimulation.t('perf_good');
                insights.push(window.mySimulation.t('insight_good_1'));
                insights.push(window.mySimulation.t('insight_good_2'));
            } else {
                tier = 'beginner';
                performance = window.mySimulation.t('perf_beginner');
                insights.push(window.mySimulation.t('insight_beginner_1'));
                insights.push(window.mySimulation.t('insight_beginner_2'));
            }
            if (finalWords > 90) insights.push(window.mySimulation.t('insight_too_long'));
            return {
                finalReplyRate: finalRate,
                totalSpecificity: finalSpec,
                wordCount: finalWords,
                performance: performance,
                tier: tier,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.replyRate < 12) return window.mySimulation.t('hint_generic');
            if (results.wordCount > 90) return window.mySimulation.t('hint_too_long');
            if (results.specificity >= 12) return window.mySimulation.t('hint_specific');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.replyRate', label: 'Reply Rate', i18nKey: 'col_reply_rate', formatter: (v) => Math.round(v) + '%' },
                { key: 'results.specificity', label: 'Specificity', i18nKey: 'col_spec', formatter: (v) => v + '/20' },
                { key: 'results.wordCount', label: 'Words', i18nKey: 'col_words' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:               `ColdOutreach`,
                    subtitle:            `The subject line, the ask, the close — write the version that gets a yes`,
                    round_label:         `Round`,
                    period_of:           `of`,
                    reply_rate_label:    `Predicted Reply Rate`,
                    specificity_label:   `Specificity Score`,
                    length_label:        `Message Length`,
                    briefing_title:      `Round Briefing`,
                    briefing_r1:         `Tuesday morning. Cursor blinking on a blank message. The recipient has 200 unread emails and will scan for 6 seconds: subject, sender, first sentence. Pick a subject line that earns the next 30 seconds. Reject Quick question (lazy) and Connecting (no value). Specific noun, specific ask, ideally a named mutual tie.`,
                    briefing_r2:         `Compose the 4-line body: who you are, why this person specifically, the micro-ask, the easy out. Cut anything that does not survive a 6-second scan. No throat-clearing. No LinkedIn paste. Specificity is respect. The ask must be time-boxed (25 minutes) and bounded (next 3 weeks).`,
                    briefing_r3:         `Sign off with name, role, company, and one link to your work — not a full LinkedIn paste. Plan exactly one follow-up at day 7. After that you are annoying without being memorable. Move on, try a different person.`,
                    decisions_heading:   `Compose`,
                    subject_label:       `Subject Line`,
                    subject_hint:        `Recipients scan in 6 seconds — be specific`,
                    subj_a:              `Quick question`,
