        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            if (idx < 0) idx = 0;
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation && window.mySimulation.t) {
                briefEl.textContent = window.mySimulation.t(round.descKey);
            }

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var blockEl = document.getElementById(this.ROUNDS[i].block);
                if (blockEl) blockEl.style.display = (i === idx) ? 'block' : 'none';
            }
        }

        _updatePreview(state) {
            if (!state || !state.domainState) return;
            var ds = state.domainState;
            var subjEl = document.getElementById('previewSubject');
            var bodyEl = document.getElementById('previewBody');
            var sigEl = document.getElementById('previewSignoff');

            if (subjEl) {
                subjEl.textContent = ds.subjectChoice ? this.SUBJECT_OPTIONS[ds.subjectChoice].text : '—';
            }

            if (bodyEl) {
                var lines = [];
                if (ds.openerChoice) lines.push(this.OPENER_OPTIONS[ds.openerChoice].text);
                if (ds.reasonChoice) {
                    var rTxt = this.REASON_OPTIONS[ds.reasonChoice].text;
                    if (rTxt) lines.push(rTxt);
                }
                if (ds.askChoice) lines.push(this.ASK_OPTIONS[ds.askChoice].text);
                if (ds.easyOutChoice) {
                    var eTxt = this.EASYOUT_OPTIONS[ds.easyOutChoice].text;
                    if (eTxt) lines.push(eTxt);
                }
                bodyEl.textContent = lines.length ? lines.join('\n\n') : '—';
            }

            if (sigEl) {
                sigEl.textContent = ds.signoffChoice ? this.SIGNOFF_OPTIONS[ds.signoffChoice].text : '';
            }
        }

        _livePreview() {
            var sim = window.mySimulation;
            if (!sim || !sim.state) return;
            var state = sim.state;
            var ds = state.domainState || {};
            var period = state.currentPeriod || 1;
            function sv(id) { var el = document.getElementById(id); return (el && el.value) ? el.value : null; }

            // Progressive draft: live for the round being composed, committed for rounds already submitted.
            var subjectChoice = (period <= 1) ? sv('subjectInput') : ds.subjectChoice;
            var openerChoice, reasonChoice, askChoice, easyOutChoice;
            if (period >= 3) {
                openerChoice = ds.openerChoice; reasonChoice = ds.reasonChoice;
                askChoice = ds.askChoice; easyOutChoice = ds.easyOutChoice;
            } else if (period === 2) {
                openerChoice = sv('openerInput'); reasonChoice = sv('reasonInput');
                askChoice = sv('askInput'); easyOutChoice = sv('easyOutInput');
            }
            var signoffChoice = (period >= 3) ? sv('signoffInput') : ds.signoffChoice;

            var subjEl = document.getElementById('previewSubject');
            var bodyEl = document.getElementById('previewBody');
            var sigEl = document.getElementById('previewSignoff');
            var NL = String.fromCharCode(10) + String.fromCharCode(10);
            if (subjEl) subjEl.textContent = (subjectChoice && this.SUBJECT_OPTIONS[subjectChoice]) ? this.SUBJECT_OPTIONS[subjectChoice].text : '—';
            if (bodyEl) {
                var lines = [];
                if (openerChoice && this.OPENER_OPTIONS[openerChoice]) lines.push(this.OPENER_OPTIONS[openerChoice].text);
                if (reasonChoice && this.REASON_OPTIONS[reasonChoice] && this.REASON_OPTIONS[reasonChoice].text) lines.push(this.REASON_OPTIONS[reasonChoice].text);
                if (askChoice && this.ASK_OPTIONS[askChoice]) lines.push(this.ASK_OPTIONS[askChoice].text);
                if (easyOutChoice && this.EASYOUT_OPTIONS[easyOutChoice] && this.EASYOUT_OPTIONS[easyOutChoice].text) lines.push(this.EASYOUT_OPTIONS[easyOutChoice].text);
                bodyEl.textContent = lines.length ? lines.join(NL) : '—';
            }
            if (sigEl) sigEl.textContent = (signoffChoice && this.SIGNOFF_OPTIONS[signoffChoice]) ? this.SIGNOFF_OPTIONS[signoffChoice].text : '';
        }

        _updateCoach(message) {
            var panel = document.getElementById('coachPanel');
            var text = document.getElementById('coachText');
            if (panel && text && message) {
                text.textContent = message;
                panel.style.display = 'block';
            }
        }
    }

